namespace TavernLens {
public class SceneState {
 public string Scene="";public bool Loading;
 public void Feed(string line){if(line.Contains("OnScenePreUnload()")){var m=Regex.Match(line,@"nextMode=(\w+)");if(m.Success)Loading=true;}if(line.Contains("OnSceneLoaded()")){var m=Regex.Match(line,@"currMode=(\w+)");if(m.Success){Scene=m.Groups[1].Value;Loading=false;}}}
 public bool InLobby {get{return !Loading&&Scene=="BACON";}}
}
public class SessionData {
 public int RatingGameCount;public Dictionary<string,RatingChange> Ratings=new Dictionary<string,RatingChange>();public int? StartRating,CurrentRating;public string Started=DateTime.UtcNow.ToString("o");public List<MatchRecord> Games=new List<MatchRecord>();
 public void Add(MatchRecord r){if(!Games.Any(g=>g.key==r.key))Games.Add(r);}
 public void ApplyRating(int value){if(!CurrentRating.HasValue){StartRating=CurrentRating=value;RatingGameCount=Games.Count;return;}if(!StartRating.HasValue)StartRating=CurrentRating;if(Games.Count>0){string key=Games.Last().key;if(Games.Count==RatingGameCount+1)Ratings[key]=new RatingChange{Before=CurrentRating.Value,After=value};else if(Games.Count==RatingGameCount&&Ratings.ContainsKey(key))Ratings[key].After=value;}CurrentRating=value;RatingGameCount=Games.Count;}
 public void Reset(){Ratings.Clear();RatingGameCount=0;Games.Clear();StartRating=CurrentRating;Started=DateTime.UtcNow.ToString("o");}
}
