public class TwinPreview : Floating {
 readonly Main main;Card card;Entity observed;
 public TwinPreview(Main m){main=m;Size=new Size(450,310);BackColor=Color.FromArgb(1,2,3);TransparencyKey=BackColor;PassThrough(true);}
 public void Display(string id,Entity unit,Control anchor,int y){Owner=anchor.FindForm();card=main.Catalog.Get(id);observed=unit;if(card==null){Hide();return;}var normal=main.Catalog.BaseId(id);var gold=main.Catalog.Golden(normal);ArtCache.Request(new[]{normal,gold==null?null:gold.id},main.Catalog.Cards.build);var screen=Screen.FromControl(anchor).WorkingArea;var p=anchor.PointToScreen(new Point(-Width-8,y));p.X=Math.Max(screen.Left,Math.Min(p.X,screen.Right-Width));p.Y=Math.Max(screen.Top,Math.Min(p.Y,screen.Bottom-Height));Place(new Rectangle(p,Size));Invalidate();}
 protected override void OnPaint(PaintEventArgs e){e.Graphics.Clear(BackColor);if(card==null)return;var normal=main.Catalog.Get(main.Catalog.BaseId(card.id))??card;var gold=main.Catalog.Golden(normal.id);var cards=gold==null?new[]{normal}:new[]{gold,normal};for(int i=0;i<cards.Length;i++){var art=ArtCache.Get(cards[i].id,main.Catalog.Cards.build);if(art!=null)e.Graphics.DrawImage(art,CardTile.Fit(art,new Rectangle(i*Width/cards.Length+3,0,Width/cards.Length-6,Height)));}}

}
public class RibbonList : Control {
 readonly Main main;readonly TwinPreview preview;public List<RibbonRow> Rows=new List<RibbonRow>();readonly List<Rectangle> bounds=new List<Rectangle>();int hovered=-1,scrollOffset,contentHeight,dragY,dragOffset;bool dragging;public int ScrollOffset {get{return scrollOffset;}}
 Rectangle ScrollTrack {get{return new Rectangle(Width-12,3,10,Math.Max(1,Height-6));}}
 Rectangle ScrollThumb {get{var t=ScrollTrack;int h=Math.Min(t.Height,Math.Max(28,(int)((double)t.Height*Height/Math.Max(1,contentHeight))));int y=t.Y+(int)((double)scrollOffset/Math.Max(1,contentHeight-Height)*(t.Height-h));return new Rectangle(t.X+2,y,6,h);}}
 public void ScrollTo(int value){scrollOffset=Math.Max(0,Math.Min(value,Math.Max(0,contentHeight-Height)));preview.Hide();hovered=-1;Invalidate();}
 protected override void OnMouseWheel(MouseEventArgs e){base.OnMouseWheel(e);ScrollTo(scrollOffset-e.Delta*48/120);}
 protected override void OnMouseDown(MouseEventArgs e){base.OnMouseDown(e);if(e.Button!=MouseButtons.Left||contentHeight<=Height||!ScrollTrack.Contains(e.Location))return;Capture=true;dragging=true;dragY=e.Y;dragOffset=scrollOffset;if(!ScrollThumb.Contains(e.Location)){ScrollTo(scrollOffset+(e.Y<ScrollThumb.Top?-Height:Height));dragOffset=scrollOffset;}}
 protected override void OnMouseUp(MouseEventArgs e){base.OnMouseUp(e);dragging=false;Capture=false;}
 public RibbonList(Main m,TwinPreview p){main=m;preview=p;Dock=DockStyle.Fill;DoubleBuffered=true;BackColor=Theme.Bg;MouseLeave+=(s,e)=>{hovered=-1;preview.Hide();Invalidate();};}
 public void SetRows(IEnumerable<RibbonRow> rows,bool preserveScroll=false){var nextRows=rows.ToList();if(preserveScroll&&String.Join("|",Rows.Select(r=>r.Title+r.Caption+r.CardId))==String.Join("|",nextRows.Select(r=>r.Title+r.Caption+r.CardId)))return;int oldScroll=scrollOffset;Rows=nextRows;hovered=-1;preview.Hide();scrollOffset=0;LayoutRows();if(preserveScroll)ScrollTo(oldScroll);Invalidate();ArtCache.Request(Rows.Select(r=>r.CardId),main.Catalog.Cards.build);}
 void LayoutRows(){bounds.Clear();int y=6;foreach(var row in Rows){int h=row.Heading?32:row.Caption==null?48:66;if(row.FullText)using(var f=Theme.Font(8))h=TextRenderer.MeasureText(row.Caption??"",f,new Size(Math.Max(50,ClientSize.Width-49),1000),TextFormatFlags.WordBreak).Height+48;bounds.Add(new Rectangle(8,y,Math.Max(20,ClientSize.Width-24),h-3));y+=h;}contentHeight=y+8;scrollOffset=Math.Min(scrollOffset,Math.Max(0,contentHeight-Height));}
 protected override void OnResize(EventArgs e){base.OnResize(e);LayoutRows();}
 int Hit(Point p){if(ScrollTrack.Contains(p))return -1;p.Y+=scrollOffset;for(int i=0;i<bounds.Count;i++)if(bounds[i].Contains(p))return i;return -1;}
 protected override void OnMouseMove(MouseEventArgs e){base.OnMouseMove(e);if(dragging){ScrollTo(dragOffset+(int)((double)(e.Y-dragY)*Math.Max(0,contentHeight-Height)/Math.Max(1,ScrollTrack.Height-ScrollThumb.Height)));return;}int at=Hit(e.Location);if(at==hovered&&preview.Visible)return;hovered=at;Cursor=at>=0&&!Rows[at].Heading?Cursors.Hand:Cursors.Default;if(at>=0&&!Rows[at].Heading&&Rows[at].CardId!=null)preview.Display(Rows[at].CardId,Rows[at].Observed,this,e.Y);else preview.Hide();Invalidate();}
 protected override void OnMouseClick(MouseEventArgs e){base.OnMouseClick(e);int i=Hit(e.Location);if(i<0)return;if(e.Button==MouseButtons.Right&&Rows[i].CardId!=null){var card=main.Catalog.Get(Rows[i].CardId);if(card!=null&&card.pool){var menu=new ContextMenuStrip();string id=main.Catalog.BaseId(card.id);menu.Items.Add(main.Settings.PinnedCards.Contains(id)?"Unwatch this minion":"Watch this minion",null,(sender,args)=>{if(!main.Settings.PinnedCards.Remove(id))main.Settings.PinnedCards.Add(id);main.SavePreferences();Invalidate();});foreach(string type in card.tribe.Split('/').Select(t=>t.Trim()).Where(t=>t!="")){string tribe=type;menu.Items.Add(main.Settings.PinnedTribes.Contains(tribe)?"Unwatch "+tribe:"Watch "+tribe,null,(sender,args)=>{if(!main.Settings.PinnedTribes.Remove(tribe))main.Settings.PinnedTribes.Add(tribe);main.SavePreferences();Invalidate();});}menu.Closed+=(sender,args)=>menu.Dispose();menu.Show(this,e.Location);}return;}if(Rows[i].Click!=null)Rows[i].Click();else if(Rows[i].CardId!=null)preview.Display(Rows[i].CardId,Rows[i].Observed,this,e.Y);}
 protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);var g=e.Graphics;for(int i=0;i<Rows.Count;i++){var r=bounds[i];r.Offset(0,-scrollOffset);if(r.Bottom<0||r.Top>Height)continue;var row=Rows[i];using(var b=new SolidBrush(row.Heading?Color.FromArgb(31,42,56):Theme.Panel))g.FillRectangle(b,r);if(!row.Heading&&row.CardId!=null){var art=ArtCache.Get(row.CardId,main.Catalog.Cards.build);if(art!=null){float cropW=art.Width*.62f,cropH=cropW*r.Height/r.Width;g.InterpolationMode=InterpolationMode.HighQualityBicubic;g.DrawImage(art,r,new RectangleF(art.Width*.19f,art.Height*.29f-cropH/2,cropW,cropH),GraphicsUnit.Pixel);using(var shade=new LinearGradientBrush(r,Color.FromArgb(235,12,17,20),Color.FromArgb(65,10,14,16),0f))g.FillRectangle(shade,r);}}using(var pen=new Pen(i==hovered?Theme.Gold:Design.Border))g.DrawRectangle(pen,r);using(var font=new Font("Segoe UI",row.Heading?9:10,FontStyle.Bold)){var text=new Rectangle(r.X+9,r.Y+4,r.Width-29,row.Caption==null?r.Height-8:26);var shadow=text;shadow.Offset(1,2);TextRenderer.DrawText(g,row.Title,font,shadow,Color.Black,TextFormatFlags.VerticalCenter|TextFormatFlags.EndEllipsis|TextFormatFlags.NoPrefix);TextRenderer.DrawText(g,(!row.Heading&&row.CardId!=null&&OverlayContext.Watched(main,row.CardId)?"★ ":"")+row.Title,font,text,Theme.Ink,TextFormatFlags.VerticalCenter|TextFormatFlags.EndEllipsis|TextFormatFlags.NoPrefix);}if(row.Caption!=null)using(var f=Theme.Font(8))TextRenderer.DrawText(g,row.Caption,f,new Rectangle(r.X+10,r.Y+31,r.Width-25,row.FullText?r.Height-37:22),Theme.Muted,row.FullText?TextFormatFlags.WordBreak:TextFormatFlags.EndEllipsis);if(row.Click!=null)using(var f=Theme.Font(15,true))TextRenderer.DrawText(g,"›",f,new Rectangle(r.Right-20,r.Y+7,18,30),Theme.Gold);}if(contentHeight>Height){using(var track=new SolidBrush(BackColor))g.FillRectangle(track,ScrollTrack);using(var thumb=new SolidBrush(dragging?Theme.Muted:Color.FromArgb(65,74,86)))g.FillRectangle(thumb,ScrollThumb);}}
}
