 void EditRating(){using(var f=new Form{Text="Session rating",Size=new Size(330,220),StartPosition=FormStartPosition.CenterScreen,FormBorderStyle=FormBorderStyle.FixedDialog,MaximizeBox=false,MinimizeBox=false,BackColor=Theme.Panel,ForeColor=Theme.Ink}){var label=Theme.Label("Enter the rating shown in Hearthstone.\nThis value is manually entered.",16,15,290,45,10,Theme.Ink);var input=new NumericUpDown{Minimum=0,Maximum=100000,Value=main.Session.CurrentRating??0,Bounds=new Rectangle(18,73,276,30),Font=Theme.Font(14)};var save=Theme.Button("Save rating",()=>{main.Session.ApplyRating((int)input.Value);main.SaveSession();f.DialogResult=DialogResult.OK;});save.SetBounds(18,121,276,34);f.Controls.AddRange(new Control[]{label,input,save});f.AcceptButton=save;f.ShowDialog();Invalidate();}}
 void TextLine(Graphics g,string text,int y,int height,int size=10,Color? color=null){using(var font=Theme.Font(size,true))TextRenderer.DrawText(g,text,font,new Rectangle(9,y,Width-18,height),color??Theme.Ink,TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter|TextFormatFlags.WordBreak|TextFormatFlags.NoPrefix);}
 protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);TextLine(e.Graphics,main.Catalog.Duos?"DUOS SESSION":"SOLO SESSION",3,28);if(Collapsed)return;TextLine(e.Graphics,"Session change",36,25);TextLine(e.Graphics,main.Session.StartRating.HasValue&&main.Session.CurrentRating.HasValue?RatingReader.Signed(main.Session.CurrentRating.Value-main.Session.StartRating.Value)+" MMR":"—",66,36,18,main.Session.CurrentRating>=main.Session.StartRating?Theme.Green:Color.Salmon);using(var p=new Pen(Design.Border)){e.Graphics.DrawLine(p,0,112,Width,112);e.Graphics.DrawLine(p,0,207,Width,207);}TextLine(e.Graphics,"MMR · live game data",115,25,9,Theme.Gold);using(var f=Theme.Font(9))using(var value=Theme.Font(18,true)){TextRenderer.DrawText(e.Graphics,"Start",f,new Rectangle(0,144,125,20),Theme.Muted,TextFormatFlags.HorizontalCenter);TextRenderer.DrawText(e.Graphics,"Current",f,new Rectangle(125,144,125,20),Theme.Muted,TextFormatFlags.HorizontalCenter);TextRenderer.DrawText(e.Graphics,main.Session.StartRating.HasValue?main.Session.StartRating.Value.ToString("N0"):"—",value,new Rectangle(0,168,125,34),Theme.Ink,TextFormatFlags.HorizontalCenter);TextRenderer.DrawText(e.Graphics,main.Session.CurrentRating.HasValue?main.Session.CurrentRating.Value.ToString("N0"):"—",value,new Rectangle(125,168,125,34),Theme.Ink,TextFormatFlags.HorizontalCenter);}TextLine(e.Graphics,main.Rating.Status,Height-100,21,8,Theme.Muted);TextLine(e.Graphics,"Latest Games",209,28);if(main.Session.Games.Count==0)TextLine(e.Graphics,"No games played this session.\nLatest 8 games will appear here.",246,49,9,Theme.Muted);else{int y=245;foreach(var result in main.Session.Games.AsEnumerable().Reverse().Take(Math.Max(1,Math.Min(8,(Height-335)/20)))){TextLine(e.Graphics,"#"+result.placement+"  "+main.Catalog.Name(result.hero)+(main.Session.Ratings.ContainsKey(result.key)?"  "+RatingReader.Signed(main.Session.Ratings[result.key].Delta):"  MMR pending"),y,20,9);y+=20;}}}
}
